//! Trust anchors: the root certificates the browser trusts.
//!
//! The roots are data, not code: `roots_data.rs` is generated by
//! `tools/mkroots.py` from a PEM bundle (see docs/BROWSER.md). Each anchor
//! is just what path validation needs: the subject name (to match issuers),
//! the public key (to check signatures) and the expiry date.

use crate::x509::Cert;
use std::borrow::Cow;

#[derive(Clone, Debug)]
pub struct TrustAnchor {
    pub name: Cow<'static, str>,
    /// DER of the subject Name (with its SEQUENCE header).
    pub subject: Cow<'static, [u8]>,
    /// DER SubjectPublicKeyInfo.
    pub spki: Cow<'static, [u8]>,
    /// Unix seconds; None = no expiry check.
    pub not_after: Option<i64>,
}

#[derive(Clone, Debug, Default)]
pub struct RootStore {
    anchors: Vec<TrustAnchor>,
}

impl RootStore {
    pub fn empty() -> RootStore {
        RootStore { anchors: Vec::new() }
    }

    /// The built-in roots.
    pub fn builtin() -> RootStore {
        let anchors = crate::roots_data::ROOTS
            .iter()
            .map(|&(name, subject, spki, not_after)| TrustAnchor {
                name: Cow::Borrowed(name),
                subject: Cow::Borrowed(subject),
                spki: Cow::Borrowed(spki),
                not_after: Some(not_after),
            })
            .collect();
        let mut store = RootStore { anchors };
        // Test builds only: tests/https.txt builds the browser with its own
        // throwaway CA in WEBNET_TEST_ROOT_PEM, so a real TLS handshake can
        // run inside QEMU without the internet. Release builds
        // (tools/build-browser.sh) refuse to run with it set.
        if let Some(pem) = option_env!("WEBNET_TEST_ROOT_PEM") {
            store.add_pem(pem);
        }
        store
    }

    pub fn len(&self) -> usize {
        self.anchors.len()
    }

    pub fn is_empty(&self) -> bool {
        self.anchors.is_empty()
    }

    /// Adds a root from its DER certificate.
    pub fn add_der(&mut self, der: &[u8]) -> Result<(), crate::x509::CertError> {
        let c = Cert::parse(der)?;
        self.anchors.push(TrustAnchor {
            name: Cow::Owned(String::from("added root")),
            subject: Cow::Owned(c.subject),
            spki: Cow::Owned(c.spki),
            not_after: Some(c.not_after),
        });
        Ok(())
    }

    /// Adds every certificate in a PEM bundle; returns how many were added.
    /// Certificates that don't parse are skipped.
    pub fn add_pem(&mut self, pem: &str) -> usize {
        pem_certs(pem).iter().filter(|d| self.add_der(d).is_ok()).count()
    }

    pub fn by_subject<'a>(&'a self, subject: &'a [u8]) -> impl Iterator<Item = &'a TrustAnchor> + 'a {
        self.anchors.iter().filter(move |a| a.subject.as_ref() == subject)
    }

    pub fn anchors(&self) -> &[TrustAnchor] {
        &self.anchors
    }
}

/// The DER bodies of the "CERTIFICATE" blocks in a PEM text.
pub fn pem_certs(pem: &str) -> Vec<Vec<u8>> {
    let mut out = Vec::new();
    let mut cur: Option<String> = None;
    for line in pem.lines() {
        let line = line.trim();
        if line == "-----BEGIN CERTIFICATE-----" {
            cur = Some(String::new());
        } else if line == "-----END CERTIFICATE-----" {
            if let Some(b64) = cur.take() {
                if let Some(d) = base64_decode(&b64) {
                    out.push(d);
                }
            }
        } else if let Some(c) = cur.as_mut() {
            c.push_str(line);
        }
    }
    out
}

/// Strict standard base64 (padding required, no stray characters).
pub fn base64_decode(s: &str) -> Option<Vec<u8>> {
    let b = s.as_bytes();
    if !b.len().is_multiple_of(4) {
        return None;
    }
    let val = |c: u8| -> Option<u32> {
        Some(match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => return None,
        } as u32)
    };
    let mut out = Vec::with_capacity(b.len() / 4 * 3);
    for (i, q) in b.chunks(4).enumerate() {
        let last = i == b.len() / 4 - 1;
        let pad = q.iter().rev().take_while(|&&c| c == b'=').count();
        if pad > 2 || (pad > 0 && !last) {
            return None;
        }
        let mut n = 0u32;
        for &c in &q[..4 - pad] {
            n = (n << 6) | val(c)?;
        }
        n <<= 6 * pad as u32;
        out.push((n >> 16) as u8);
        if pad < 2 {
            out.push((n >> 8) as u8);
        }
        if pad < 1 {
            out.push(n as u8);
        }
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtin_roots_parse() {
        let r = RootStore::builtin();
        assert!(r.len() > 50, "only {} roots", r.len());
        let mut ok = 0;
        for a in r.anchors() {
            if crate::x509::PublicKey::from_spki(&a.spki).is_ok() {
                ok += 1;
            }
        }
        // Nearly all roots have keys we support (RSA 2048-4096, P-256, P-384).
        assert!(ok * 10 >= r.len() * 9, "{ok} of {} root keys usable", r.len());
    }

    #[test]
    fn base64() {
        assert_eq!(base64_decode("aGVsbG8=").unwrap(), b"hello");
        assert_eq!(base64_decode("aGk=").unwrap(), b"hi");
        assert!(base64_decode("aGk").is_none());
        assert!(base64_decode("a=Gk").is_none());
    }
}
